Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include<bits/stdc++.h>
#define maxn 5000010
#define inf 1000000000
#define p(x,k) (x+(k-1)*n)
using namespace std;
template<typename T> inline void read(T &x)
{
    x=0;char c=getchar();bool flag=false;
    while(!isdigit(c)){if(c=='-')flag=true;c=getchar();}
    while(isdigit(c)){x=(x<<1)+(x<<3)+(c^48);c=getchar();}
    if(flag)x=-x;
}
int n,m,k,v1,v2,s,t;
int dis[maxn];
bool vis[maxn];
struct edge
{
    int to,nxt,v,c;
}e[maxn];
int head[maxn],edge_cnt=1;
void add(int from,int to,int val,int cost)
{
	e[++edge_cnt]=(edge){to,head[from],val,cost},head[from]=edge_cnt;
    e[++edge_cnt]=(edge){from,head[to],0,-cost},head[to]=edge_cnt;
}
bool spfa()
{
    queue<int> q;
    for(int i=s;i<=t;++i) dis[i]=inf,vis[i]=false;
    q.push(s),dis[s]=0,vis[s]=true;
    while(!q.empty())
    {
        int x=q.front();
        q.pop(),vis[x]=false;
        for(int i=head[x];i;i=e[i].nxt)
        {
            int y=e[i].to,c=e[i].c;
            if(dis[y]<=dis[x]+c||!e[i].v) continue;
            dis[y]=dis[x]+c;
            if(!vis[y]) vis[y]=true,q.push(y);
        }
    }
    return dis[t]!=inf;
}
int dfs(int x,int lim)
{
    if(x==t) return lim;
    vis[x]=true;
    int flow,res=lim;
    for(int i=head[x];i;i=e[i].nxt)
    {
        int y=e[i].to,v=e[i].v;
        if(dis[y]!=dis[x]+e[i].c||!v||vis[y]) continue;
        if(flow=dfs(y,min(res,v)))
        {
            res-=flow;
            e[i].v-=flow;
            e[i^1].v+=flow;
            if(!res) break;
        }
    }
    return lim-res;
}
int dinic()
{
    int flow,sum=0;
    while(spfa())
        while(flow=dfs(s,inf))
            sum+=flow*dis[t];
    return sum;
}
int main()
{
    read(n),read(m),read(k),read(v1),read(v2),t=p(n,110)+1;
    for(int i=2;i<=110;++i) add(p(1,i),t,inf,0);
    for(int i=2;i<=n;++i)
        for(int j=1;j<110;++j)
            add(p(i,j),p(i,j+1),inf,v1);
    for(int i=1,x;i<=k;++i) read(x),add(s,p(x,1),1,0);
    for(int i=1;i<=m;++i)
    {
        int x,y;
        read(x),read(y);
        for(int j=1;j<110;++j)
            for(int l=1;l<=k;++l)
                add(p(x,j),p(y,j+1),1,v2*(2*l-1)+v1),add(p(y,j),p(x,j+1),1,v2*(2*l-1)+v1);
    }
    printf("%d",dinic());
    return 0;
}
